import { FACE_SHAPES } from './shapes';
import type { FaceShapeName } from './shapes';

/**
 * The shape galleries.
 *
 * The files in public/assets/faceshapes are placeholders generated by
 * scripts/generate-face-placeholders.mjs. They are real 1:1 PNGs on disk, so
 * replacing one with a real photograph is an overwrite: same name, same
 * extension, same dimensions. Nothing here needs to change when that happens.
 *
 * This module is the single place that knows how an image is addressed, so the
 * naming convention is stated once rather than repeated in components.
 */

/** Images per shape. Matches what the generator writes. */
export const GALLERY_SIZE = 10;

const ROOT = '/assets/faceshapes';

/** 01..10, so a gallery sorts the way a human numbers them. */
const slots = (count: number): string[] =>
  Array.from({ length: count }, (_, index) => String(index + 1).padStart(2, '0'));

export const shapeGallery = (shape: FaceShapeName): string[] =>
  slots(GALLERY_SIZE).map((slot) => `${ROOT}/${shape}/${slot}.png`);

export const trendingGallery = (): string[] =>
  slots(GALLERY_SIZE).map((slot) => `${ROOT}/trending/${slot}.png`);

export const galleryFor = (shape: FaceShapeName | null): string[] =>
  shape ? shapeGallery(shape) : trendingGallery();

/** Every folder the generator is expected to have produced. */
export const EXPECTED_GALLERY_DIRS: string[] = [...FACE_SHAPES, 'trending'];